import{_ as c,C as e,o as h,c as g,j as o,a as r,E as a,a2 as d}from"./chunks/framework.CQjSGuJt.js";const _=JSON.parse('{"title":"2. Core loop","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/core-loop.md","filePath":"gdd/core-loop.md"}'),i={name:"gdd/core-loop.md"};function s(l,n,u,p,x,m){const t=e("Badge");return h(),g("div",null,[n[0]||(n[0]=o("h1",{id:"_2-core-loop",tabindex:"-1"},[r("2. Core loop "),o("a",{class:"header-anchor",href:"#_2-core-loop","aria-label":'Permalink to "2. Core loop"'},"​")],-1)),a(t,{type:"tip",text:"Live"}),n[1]||(n[1]=d(' Luật dưới đây lấy từ đặc tả bản gốc Fish Bus (<code>GAME_SPEC.md</code> v1); đã có trong code Phaser (<code>src/core/</code>).<h2 id="_2-1-thanh-phan" tabindex="-1">2.1 Thành phần <a class="header-anchor" href="#_2-1-thanh-phan" aria-label="Permalink to &quot;2.1 Thành phần&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Thành phần</th><th>Mô tả</th></tr></thead><tbody><tr><td><strong>Ống (Pipe)</strong></td><td>Đường khép kín (đa giác bo góc) do level định nghĩa. Cá chạy <strong>một chiều</strong>, tốc độ đều <code>pipeSpeed</code> (px/s).</td></tr><tr><td><strong>Ống hở có cổng</strong></td><td>Ống có thể hở (<code>open</code>): điểm đầu và điểm cuối là 2 <strong>cổng</strong>. Cá chui vào cổng cuối thì ra <strong>ngay lập tức</strong> ở cổng đầu, nên về luật ống vẫn là một vòng; chiều dài vòng <code>L</code> không tính đoạn nối 2 cổng.</td></tr><tr><td><strong>Ô ống (Slot)</strong></td><td>Ống được chia đều thành <code>C = floor(L / slotLength)</code> ô. Mỗi ô chứa <strong>0 hoặc 1 nấc cá</strong> (1 màu). <code>C</code> = sức chứa ống.</td></tr><tr><td><strong>Xe (Bus)</strong></td><td>Đứng yên tại chỗ. Có <code>capacity</code> = <strong>4 nấc (cố định)</strong>. <em>(Bản gốc cho phép 1..4; đã chốt dùng 4 cho Fish Loop.)</em> Nội dung là <strong>ngăn xếp</strong>: phần tử đầu = đầu xe, phần tử cuối = <strong>đuôi xe</strong>.</td></tr><tr><td><strong>Cổng (Port)</strong></td><td>Mỗi xe có 1 điểm trên ống (<code>portS</code>, toạ độ theo chiều dài ống). Mặc định = điểm đầu tiên trên ống khi đi <strong>thẳng theo hướng đuôi xe</strong> (cá ra thẳng từ đuôi); nếu hướng đó không gặp ống thì lấy điểm ống gần đuôi xe nhất. Cá ra và vào xe đều qua cổng này.</td></tr><tr><td><strong>Nấc (Unit)</strong></td><td>Đơn vị logic nhỏ nhất: 1 nấc = 1 bể cá 1 màu. Về hình ảnh, 1 nấc hiển thị <code>fishPerUnit</code> con cá.</td></tr></tbody></table><h2 id="_2-2-xa-ca-nguoi-choi-tap-xe" tabindex="-1">2.2 Xả cá (người chơi tap xe) <a class="header-anchor" href="#_2-2-xa-ca-nguoi-choi-tap-xe" aria-label="Permalink to &quot;2.2 Xả cá (người chơi tap xe)&quot;">​</a></h2><ol><li>Xe bị khoá (đã ✓) hoặc rỗng → tap không có tác dụng (rung nhẹ).</li><li>Lấy <strong>cụm cùng màu liền nhau ở đuôi</strong> xe, độ dài <code>k</code>.</li><li><code>free = min(số ô trống trong ống, N − số nấc đang trên ống) − số nấc đang chờ vào ống (của mọi xe)</code>. <code>N</code> = <code>pipeLimit</code> của level (mặc định 5): số nấc tối đa được chạy trên ống cùng lúc.</li><li><code>n = min(k, free)</code>. Nếu <code>n = 0</code> → báo &quot;Ống đầy&quot;, không xả.</li></ol><p>Bộ đếm <code>x/N</code> trên HUD: <code>x</code> = số nấc đang chạy trên ống. Nấc rơi xuống ống → <code>x</code> tăng 1; nấc vào xe → <code>x</code> giảm 1. Khi <code>x = N</code> số chuyển màu đỏ nhạt. 5. <code>n</code> nấc rời xe ngay (xe không còn chứa chúng) và vào <strong>hàng chờ của cổng</strong> xe đó. 6. Mỗi khi một <strong>ô trống</strong> đi qua cổng, nấc đầu hàng chờ nhảy vào ô đó. Ô ghi nhớ <code>source = xe nguồn</code>, <code>traveled = 0</code>. 7. Có thể tap tiếp khi hàng chờ chưa xả hết. Cụm tiếp theo xếp sau trong hàng chờ.</p><h2 id="_2-3-ca-vao-xe-tu-đong" tabindex="-1">2.3 Cá vào xe (tự động) <a class="header-anchor" href="#_2-3-ca-vao-xe-tu-đong" aria-label="Permalink to &quot;2.3 Cá vào xe (tự động)&quot;">​</a></h2><p>Khi một ô có cá màu <code>c</code> đi qua cổng của xe <code>B</code>, cá vào <code>B</code> nếu <strong>đủ tất cả</strong> điều kiện:</p><ul><li><code>B</code> chưa hoàn thành và còn chỗ trống (<code>stack.length &lt; capacity</code>).</li><li><code>B</code> rỗng <strong>hoặc</strong> nấc ở đuôi <code>B</code> có màu <code>c</code>.</li><li><code>B</code> không có hàng chờ xả.</li><li>Không phải trường hợp <code>source = B</code> và <code>traveled &lt; L</code> (cá <strong>không quay lại xe nguồn</strong> khi chưa chạy hết 1 vòng).</li><li><strong>Ưu tiên xe cùng màu:</strong> nếu <code>B</code> rỗng mà đang có xe khác chưa ✓, còn chỗ, không rỗng và nấc ở đuôi màu <code>c</code>, thì cá <strong>không vào <code>B</code></strong> (đi ngang xe trống cũng bỏ qua) mà chạy tiếp tìm xe đó. Khi các xe như vậy đã đầy, phần còn dư mới được vào xe trống (thường sau thêm 1 vòng). Tránh việc 2 xe cùng có nấc màu <code>c</code> cứ chuyền qua lại cho nhau.</li></ul><p>Nếu nhiều cổng trùng vị trí, xét theo thứ tự xe trong level.</p><h2 id="_2-4-hoan-thanh-xe" tabindex="-1">2.4 Hoàn thành xe <a class="header-anchor" href="#_2-4-hoan-thanh-xe" aria-label="Permalink to &quot;2.4 Hoàn thành xe&quot;">​</a></h2><p>Xe <strong>đủ <code>capacity</code> nấc và tất cả cùng màu</strong> → hoàn thành: nắp đóng lại che các bể, dấu ✓ hiện trên nắp, xe bị khoá vĩnh viễn (không xả, không nhận).</p><h2 id="_2-5-session-loop-va-long-term-loop" tabindex="-1">2.5 Session loop và long-term loop <a class="header-anchor" href="#_2-5-session-loop-va-long-term-loop" aria-label="Permalink to &quot;2.5 Session loop và long-term loop&quot;">​</a></h2><p><em>TBD</em></p>',18))])}const k=c(i,[["render",s]]);export{_ as __pageData,k as default};
